// Exercise collection decoding, response contracts, and failure preservation with an in-memory repository.
// Generated by Codex and not thoroughly checked for correctness.
func TestCollectionHandlers(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, tc := range []struct {
		suffix, body string
		status       int
	}{
		{"move", `{"moves":[{"problem_id":"A","before_problem_id":"B"}]}`, 200},
		{"move", `{"moves":[{"problem_id":"A","after_problem_id":"B"}]}`, 200},
		{"move", `{"moves":[{"problem_id":"A","before_problem_id":"missing"}]}`, 409},
		{"move", `{"moves":[{"problem_id":"A","before_problem_id":"A"}]}`, 400},
		{"move", `{"moves":[{"problem_id":"A","unknown":true}]}`, 400},
		{"bulk", `{"items":[{"problem_id":"C","notes":"hi"}]}`, 200},
		{"bulk", `{"items":[{"problem_id":"C","position":1}]}`, 400},
		{"bulk", `{"items":[{"problem_id":"C","status":"bad"}]}`, 400},
		{"bulk", `{"items":[{"problem_id":"C","notes":"\u0000"}]}`, 400},
		{"remove", `{"problem_ids":["A"]}`, 200},
		{"remove", `{"problem_ids":5}`, 400},
		{"move", `{"moves":5}`, 400},
		{"bulk", `{"items":5}`, 400},
		{"bulk", `{"items":[{"problem_id":"C","notes":"` + string([]byte{0xff}) + `"}]}`, 400},
		{"move", `{`, 400},
		{"bulk", `{} {}`, 400},
	} {
		t.Run(tc.suffix+tc.body, func(t *testing.T) {
			repository := newMockRepository()
			repository.expectedContext = t.Context()
			for index, id := range []string{"A", "B"} {
				item := newListItemFixture()
				item.ProblemId = id
				item.Position = int64(index+1) * items.PositionGap
				repository.storeItem(item)
			}
			before := map[string]items.ListItem{}
			for id, item := range repository.items[testListID] {
				before[id] = item
			}
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, fmt.Sprintf("%s/%d/items/%s", testListsPath, testListID, tc.suffix), tc.body)
			assertResponseStatus(t, response, tc.status)
			if tc.status >= 400 && !reflect.DeepEqual(before, repository.items[testListID]) {
				t.Fatal("failed request changed records")
			}
			if tc.status == 200 {
				var result items.CollectionResult
				if err := json.Unmarshal(response.Body.Bytes(), &result); err != nil {
					t.Fatal(err)
				}
				if result.Order == nil {
					t.Fatal("missing order")
				}
			}
		})
	}
}

// Verify invalid list identifiers and inaccessible lists produce stable HTTP errors.
// Generated by Codex and not thoroughly checked for correctness.
func TestCollectionHandlersRejectInvalidOrUnownedList(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, tc := range []struct{ suffix, body string }{
		{"bulk", `{"items":[{"problem_id":"A"}]}`},
		{"move", `{"moves":[{"problem_id":"A"}]}`},
		{"remove", `{"problem_ids":["A"]}`},
	} {
		for _, id := range []string{"invalid", fmt.Sprint(testListID)} {
			repository := newMockRepository()
			repository.expectedContext = t.Context()
			clearLists(repository)
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, fmt.Sprintf("%s/%s/items/%s", testListsPath, id, tc.suffix), tc.body)
			want := http.StatusNotFound
			if id == "invalid" {
				want = http.StatusBadRequest
			}
			assertResponseStatus(t, response, want)
		}
	}
}

// BulkAdd simulate append responses over shared in-memory state; database atomicity is tested separately.
func (repository mockListItemRepository) BulkAdd(ctx context.Context, userID, listID int64, input []items.ListItem) (*items.CollectionResult, error) {
	if len(input) == 0 {
		return nil, items.ErrInvalidOperation
	}
	seen := map[string]bool{}
	for _, item := range input {
		if err := items.ValidateProblemID(item.ProblemId); err != nil {
			return nil, err
		}
		if seen[item.ProblemId] {
			return nil, items.ErrInvalidOperation
		}
		seen[item.ProblemId] = true
		if err := item.Practice.Normalize(); err != nil {
			return nil, err
		}
	}
	repository.contextMismatch = repository.contextMismatch || ctx != repository.expectedContext
	for _, item := range input {
		repository.record(repositoryCall{operation: createListItemOperation, userID: userID, listID: listID, problemID: item.ProblemId})
	}
	if err := repository.operationErrors[createListItemOperation]; err != nil {
		return nil, err
	}
	if _, ok := repository.ownedList(userID, listID); !ok {
		return nil, items.ErrListNotFound
	}
	result := &items.CollectionResult{Order: []items.OrderedItem{}}
	last := int64(0)
	for _, item := range repository.items[listID] {
		if item.Position > last {
			last = item.Position
		}
	}
	for _, item := range input {
		if _, exists := repository.items[listID][item.ProblemId]; exists {
			result.Skipped = append(result.Skipped, item.ProblemId)
			continue
		}
		last += items.PositionGap
		item.Position = last
		item.ListId = listID
		item.CreatedAt = testItemCreatedAt()
		repository.storeItem(item)
		result.Added = append(result.Added, item)
	}
	for _, item := range repository.items[listID] {
		result.Order = append(result.Order, items.OrderedItem{ProblemID: item.ProblemId, Position: item.Position})
	}
	sort.Slice(result.Order, func(i, j int) bool { return result.Order[i].Position < result.Order[j].Position })
	return result, nil
}

// MoveItems models atomic position changes in memory; real SQL behavior belongs to integration tests.
func (repository mockListItemRepository) MoveItems(ctx context.Context, userID, listID int64, moves []items.Move) (*items.CollectionResult, error) {
	if err := items.ValidateMoves(moves); err != nil {
		return nil, err
	}
	stored, err := repository.GetItems(ctx, userID, listID)
	if err != nil {
		return nil, err
	}
	pending := map[string]items.ListItem{}
	for _, item := range stored {
		pending[item.ProblemId] = item
	}
	for _, move := range moves {
		item, exists := pending[move.ProblemID]
		if !exists {
			return nil, items.ErrOrderConflict
		}
		anchor := move.Before
		if move.After != nil {
			anchor = move.After
		}
		left, right := int64(0), items.MaxPosition
		if anchor != nil {
			target, exists := pending[*anchor]
			if !exists {
				return nil, items.ErrOrderConflict
			}
			if move.Before != nil {
				right = target.Position
			} else {
				left = target.Position
			}
		}
		for id, other := range pending {
			if id == move.ProblemID {
				continue
			}
			if move.Before != nil {
				if other.Position < right && other.Position > left {
					left = other.Position
				}
			} else if move.After != nil {
				if other.Position > left && other.Position < right {
					right = other.Position
				}
			} else if other.Position > left {
				left = other.Position
			}
		}
		if item.Position > left && item.Position < right {
			continue
		}
		item.Position, _ = items.PositionBetween(left, right)
		pending[move.ProblemID] = item
	}
	result := &items.CollectionResult{Order: []items.OrderedItem{}}
	for _, item := range pending {
		repository.storeItem(item)
		result.Order = append(result.Order, items.OrderedItem{ProblemID: item.ProblemId, Position: item.Position})
	}
	sort.Slice(result.Order, func(i, j int) bool { return result.Order[i].Position < result.Order[j].Position })
	return result, nil
}

// BulkRemove simulate selected list contents removal for handler tests; SQL rollback is outside this mock.
func (repository mockListItemRepository) BulkRemove(ctx context.Context, userID, listID int64, ids []string) (*items.CollectionResult, error) {
	for _, id := range ids {
		if err := repository.deleteItem(ctx, userID, &items.ListItem{ListId: listID, ProblemId: id}); err != nil {
			return nil, err
		}
	}
	return &items.CollectionResult{Order: []items.OrderedItem{}}, nil
}
